// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(uint256 depositVal, uint256 collectAmt) public {
        vm.assume(depositVal > 0);
        vm.assume(collectAmt > 0);
        vm.assume(collectAmt <= depositVal);

        address actor = address(0x1234);

        vm.deal(actor, depositVal);
        vm.prank(actor);
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        vm.prank(actor);
        c.Deposit{value: depositVal}();

        uint256 balanceBefore = c.balances(actor);

        vm.prank(actor);
        c.Collect(collectAmt);

        uint256 balanceAfter = c.balances(actor);

        assertTrue(balanceBefore == depositVal && balanceAfter == depositVal - collectAmt);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
